arguments.command:
python3 -I - <<'EOF'
import json,numpy as np
o=json.load(open('geo0.json'))
A=6378137.0;c=np.cos(np.radians(34.87))*np.pi/180*A;d=np.pi/180*A
from collections import defaultdict
for T in [13,34,106]:
    s=[x for x in o if x['track']==T]
    crs=sorted(set(x['cr'] for x in s))
    mlat={cr:np.mean([x['lat'] for x in s if x['cr']==cr]) for cr in crs}
    mlon={cr:np.mean([x['lon'] for x in s if x['cr']==cr]) for cr in crs}
    byf=defaultdict(list)
    for x in s: byf[x['file']].append(((x['lon']-mlon[x['cr']])*c,(x['lat']-mlat[x['cr']])*d))
    print('track',T)
    for f in sorted(byf):
        a=np.array(byf[f]); print(f[42:57], '%6.2f %6.2f  spread %.2f'%(a[:,0].mean(),a[:,1].mean(),a[:,1].std()))
EOF

